do $$
declare
  v_total integer;
  v_bad_correct integer;
  v_duplicate integer;
begin
  select count(*) into v_total
  from public.question_bank
  where discipline='mantrailing';

  if v_total <> 920 then
    raise exception 'Conteggio MANTRAILING errato: %, atteso 920', v_total;
  end if;

  select count(*) into v_bad_correct
  from public.question_bank
  where discipline='mantrailing'
    and correct_option not between 0 and 3;

  if v_bad_correct <> 0 then
    raise exception 'Sono presenti % correct_option non validi', v_bad_correct;
  end if;

  select count(*) into v_duplicate
  from (
    select lower(trim(question_text)), count(*)
    from public.question_bank
    where discipline='mantrailing'
    group by lower(trim(question_text))
    having count(*) > 1
  ) d;

  if v_duplicate <> 0 then
    raise exception 'Sono presenti % gruppi di domande duplicate', v_duplicate;
  end if;
end $$;

commit;

select discipline, count(*) as totale
from public.question_bank
group by discipline
order by discipline;

select category, count(*) as totale
from public.question_bank
where discipline='mantrailing'
group by category
order by category;
